// Run inside Electron: extract the signature from signInvoiceXML, write it to disk for openssl verification
const crypto = require('crypto');
const forge = require('node-forge');
const fs = require('fs');
const zatca = require('./electron/zatca_phase2.cjs');

const payload = Buffer.from('test payload to sign', 'utf8');

// Generate key inside Electron to prove extraction works end-to-end inside Electron
// We can't use native crypto for secp256k1 keygen either (UNKNOWN_GROUP) — so read from the key generated by Node earlier
const privateKey = fs.readFileSync('temp_test_key.pem', 'utf8');
const pubKey = fs.readFileSync('pub.pem', 'utf8');

// Use the new signEcdsaSha256 via the zatca module internals — but it's not exported
// Instead, replicate the exact call path directly:
const EC = require('elliptic').ec;
const ec = new EC('secp256k1');

function extractPrivateKeyHex(pem) {
    const msg = forge.pem.decode(pem)[0];
    const asn1Obj = forge.asn1.fromDer(msg.body);
    if (asn1Obj.value[1].type === forge.asn1.Type.SEQUENCE && asn1Obj.value[2].type === forge.asn1.Type.OCTETSTRING) {
        const ecPrivateKeyAsn1 = forge.asn1.fromDer(asn1Obj.value[2].value);
        return forge.util.bytesToHex(ecPrivateKeyAsn1.value[1].value);
    } else if (asn1Obj.value[1].type === forge.asn1.Type.OCTETSTRING) {
        return forge.util.bytesToHex(asn1Obj.value[1].value);
    }
    throw new Error('Unsupported PEM format');
}

console.log('--- Environment ---');
console.log('Node version:', process.versions.node);
console.log('Electron version:', process.versions.electron || 'N/A');

try {
    const dHex = extractPrivateKeyHex(privateKey);
    console.log('D scalar extracted, length:', dHex.length, 'chars');
    
    const hash = crypto.createHash('sha256').update(payload).digest();
    const keyPair = ec.keyFromPrivate(dHex, 'hex');
    const sigDer = Buffer.from(keyPair.sign(hash).toDER());
    
    fs.writeFileSync('electron.sig', sigDer);
    console.log('Signature written to electron.sig, length:', sigDer.length);
} catch(e) {
    console.error('FAILED:', e.message);
}

if (process.versions.electron) {
    const { app } = require('electron');
    app.quit();
}
